import { useRoleBrowseActionQuery } from "../../sdk/abac/RoleBrowseAction";
import { type RoleDto } from "../../sdk/abac/RoleDto";

// Adapts useRoleBrowseActionQuery (the generated per-action hook, returning a raw
// @tanstack/react-query result whose payload is the {data: {items, ...}} envelope)
// into the {query, items, keyExtractor} shape FormSelect/FormSelectMultiple's
// querySource prop expects. Replaces the old useGetRoles hook (deleted along with the
// rest of the legacy "Generated by fireback 1.3.2" sdk/modules tree), which returned
// that shape directly.
export const useRolesQuerySource = () => {
  const query = useRoleBrowseActionQuery({});
  const items = ((query.data as any)?.data?.items ?? []) as RoleDto[];
  return {
    query: query as any,
    items,
    keyExtractor: (item: RoleDto) => item.uniqueId,
  };
};
